package calc

func triples(n int64) int64 {
	var count int64
	for c := int64(1); c < n; c++ {
		for b := int64(1); b < c; b++ {
			for a := int64(1); a < b; a++ {
				if a*a+b*b == c*c {
					count++
				}
			}
		}
	}
	return count
}

package calc

import "testing"

func TestTriples(t *testing.T) {
	if got := triples(5); got != 1 {
		t.Errorf("triples(5) = %d, want 1", got)
	}
	if got := triples(20); got != 6 {
		t.Errorf("triples(20) = %d, want 6", got)
	}
}
